473	    /** Region whose postcode range contains the given postcode, or {@code null} when none does. */
474	    private static String regionForPostcode(String postcode) {
475	        if (postcode == null) {
476	            return null;
477	        }
478	        int value;
479	        try {
480	            value = Integer.parseInt(postcode.trim());
481	        }
482	        catch (NumberFormatException ex) {
483	            return null;
484	        }
485	        for (Map.Entry<String, int[]> entry : REGION_POSTCODES.entrySet()) {
486	            int[] range = entry.getValue();
487	            if (value >= range[0] && value <= range[1]) {
488	                return entry.getKey();
489	            }
490	        }
491	        return null;
492	    }
493	
494	    /**
495	     * The owner's identity key, the single derived value all duplicate detection is based on. It is
496	     * the full lower-case hex SHA-256 digest of {@code normalizedTelephone + '|' + lowerEmail + '|' +
497	     * soundex(lastName)}, where the telephone is the stored E.164 value, the email is the stored
498	     * lower-cased value (empty when absent) and the last-name segment is the American Soundex code of
499	     * the last name. Two owners are duplicates only when their whole identity keys are equal, so
500	     * owners sharing a last name (by soundex) and postcode but carrying different telephones no longer
501	     * collide here — they are surfaced as a soft (possible) duplicate instead.
502	     */
503	    @Transient
504	    public String getIdentityKey() {
505	        String telephonePart = this.telephone == null ? "" : this.telephone;
506	        String emailPart = (this.email == null || this.email.isBlank()) ? "" : this.email;
507	        String key = telephonePart + "|" + emailPart + "|" + soundex(getLastName());
508	        return sha256Hex(key);
509	    }
510	
511	    /**
512	     * The American Soundex code of {@code name}: the first letter followed by three digits (padded
513	     * with {@code '0'} when there are too few coded consonants, truncated to four characters
514	     * otherwise). Non-letters are ignored; a {@code null}, blank, or letter-free value yields the
515	     * empty string. Consonants are grouped b/f/p/v=1, c/g/j/k/q/s/x/z=2, d/t=3, l=4, m/n=5, r=6;
516	     * adjacent same-coded letters (and same-coded letters separated only by {@code h}/{@code w}) are
517	     * coded once, while a vowel between them causes both to be coded.
518	     */
519	    public static String soundex(String name) {
520	        if (name == null) {
521	            return "";
522	        }
523	        StringBuilder letters = new StringBuilder();
524	        for (char c : name.toUpperCase(Locale.ROOT).toCharArray()) {
525	            if (c >= 'A' && c <= 'Z') {
526	                letters.append(c);
527	            }
528	        }
529	        if (letters.length() == 0) {
530	            return "";
531	        }
532	        StringBuilder code = new StringBuilder().append(letters.charAt(0));
533	        char prevCode = soundexCode(letters.charAt(0));
534	        for (int i = 1; i < letters.length() && code.length() < 4; i++) {
535	            char c = letters.charAt(i);
536	            if (c == 'H' || c == 'W') {
537	                // Acts as a connector: same-coded consonants either side stay adjacent.
538	                continue;
539	            }
540	            if (c == 'A' || c == 'E' || c == 'I' || c == 'O' || c == 'U' || c == 'Y') {
541	                // A vowel separates same-coded consonants, so both are coded.
542	                prevCode = '0';
543	                continue;
544	            }
545	            char digit = soundexCode(c);
546	            if (digit != '0' && digit != prevCode) {
547	                code.append(digit);
548	            }
549	            prevCode = digit;
550	        }
551	        while (code.length() < 4) {
552	            code.append('0');
553	        }
554	        return code.toString();
555	    }
556	
557	    private static char soundexCode(char c) {
558	        switch (c) {
559	            case 'B': case 'F': case 'P': case 'V':
560	                return '1';
561	            case 'C': case 'G': case 'J': case 'K': case 'Q': case 'S': case 'X': case 'Z':
562	                return '2';
563	            case 'D': case 'T':
564	                return '3';
565	            case 'L':
566	                return '4';
567	            case 'M': case 'N':
568	                return '5';
569	            case 'R':
570	                return '6';
571	            default:
572	                return '0';
573	        }
574	    }
575	
576	    /** The full lower-case hex SHA-256 digest of the UTF-8 bytes of {@code value}. */
577	    private static String sha256Hex(String value) {
578	        try {
579	            byte[] digest = java.security.MessageDigest.getInstance("SHA-256")
580	                .digest(value.getBytes(java.nio.charset.StandardCharsets.UTF_8));
581	            StringBuilder sb = new StringBuilder(digest.length * 2);
582	            for (byte b : digest) {
583	                sb.append(String.format("%02x", b));
584	            }
585	            return sb.toString();
586	        }
587	        catch (java.security.NoSuchAlgorithmException e) {
588	            throw new IllegalStateException("SHA-256 not available", e);
589	        }
590	    }
