67	@RestController
68	@CrossOrigin(exposedHeaders = "errors, content-type")
69	@RequestMapping("/api")
70	public class OwnerRestControllerV1 implements OwnersApi {
71	
72	    private static final Logger AUDIT = LoggerFactory.getLogger("AUDIT");
73	
74	    /**
75	     * Monotonically increasing sequence for the structured OWNER_CREATED audit events, incremented
76	     * once per successful create so every emitted event carries a strictly greater {@code seq} than
77	     * the one before it.
78	     */
79	    private static final java.util.concurrent.atomic.AtomicLong AUDIT_EVENT_SEQ =
80	        new java.util.concurrent.atomic.AtomicLong();
81	
82	    /**
83	     * The request header carrying a client-supplied idempotency token for owner creation. When a
84	     * create repeats with a token already seen, the originally created owner is returned with 200
85	     * instead of creating a duplicate.
86	     */
87	    private static final String IDEMPOTENCY_KEY_HEADER = "Idempotency-Key";
88	
89	    /**
90	     * Remembers, per idempotency key, the id of the owner created by the first request that carried
91	     * that key, so a repeat with the same key resolves back to the original owner instead of
92	     * creating a duplicate.
93	     */
94	    private final java.util.Map<String, Integer> idempotentCreates = new java.util.concurrent.ConcurrentHashMap<>();
95	
96	    private final ClinicService clinicService;
97	
98	    private final OwnerMapper ownerMapper;
99	
100	    private final PetMapper petMapper;
101	
102	    private final VisitMapper visitMapper;
103	
104	    public OwnerRestControllerV1(ClinicService clinicService,
105	                                 OwnerMapper ownerMapper,
106	                                 PetMapper petMapper,
107	                                 VisitMapper visitMapper) {
108	        this.clinicService = clinicService;
109	        this.ownerMapper = ownerMapper;
110	        this.petMapper = petMapper;
111	        this.visitMapper = visitMapper;
