114	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
115	    @Override
116	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
117	        Collection<Owner> owners;
118	        if (lastName != null) {
119	            owners = this.clinicService.findOwnerByLastName(lastName);
120	        } else {
121	            owners = this.clinicService.findAllOwners();
122	        }
123	        if (owners.isEmpty()) {
124	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
125	        }
126	        boolean bulkSignupWarning = isBulkSignupWarning();
127	        List<OwnerDto> ownerDtos = ownerMapper.toOwnerDtoCollection(owners);
128	        ownerDtos.forEach(ownerDto -> {
129	            ownerDto.setBulkSignupWarning(bulkSignupWarning);
130	            ownerDto.setCapacityWarning(isCityApproachingCapacity(ownerDto.getCity()));
131	        });
132	        return new ResponseEntity<>(ownerDtos, HttpStatus.OK);
133	    }
