135	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
136	    @Override
137	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
138	        Owner owner = this.clinicService.findOwnerById(ownerId);
139	        if (owner == null) {
140	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
141	        }
142	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
143	        ownerDto.setBulkSignupWarning(isBulkSignupWarning());
144	        ownerDto.setCapacityWarning(isCityApproachingCapacity(owner.getCity()));
145	        return new ResponseEntity<>(ownerDto, HttpStatus.OK);
146	    }
147	
148	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
149	    @Override
150	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
151	        // Idempotent create: when the request carries an 'Idempotency-Key' already seen, return the
152	        // owner originally created for that key with 200, instead of creating a duplicate.
153	        String idempotencyKey = currentIdempotencyKey();
154	        if (idempotencyKey != null) {
155	            Integer existingId = idempotentCreates.get(idempotencyKey);
156	            if (existingId != null) {
157	                Owner existing = this.clinicService.findOwnerById(existingId);
158	                if (existing != null) {
159	                    OwnerDto existingDto = ownerMapper.toOwnerDto(existing);
160	                    existingDto.setBulkSignupWarning(isBulkSignupWarning());
161	                    existingDto.setCapacityWarning(isCityApproachingCapacity(existing.getCity()));
162	                    return new ResponseEntity<>(existingDto, HttpStatus.OK);
163	                }
164	            }
165	        }
166	        // Prefer the structured address fields when present; the flat 'address' input remains accepted
167	        // for backward compatibility. When structured, the stored/returned address is the composed
168	        // normalized addressLine1 (with a single space and the normalized addressLine2 appended when
169	        // addressLine2 is present); otherwise it is the normalized flat 'address'.
170	        boolean structured = !isBlank(ownerFieldsDto.getAddressLine1());
171	        String addressLine1 = normalizeAddress(ownerFieldsDto.getAddressLine1());
172	        String addressLine2 = normalizeAddress(ownerFieldsDto.getAddressLine2());
173	        String address;
174	        if (structured) {
175	            address = addressLine2.isEmpty() ? addressLine1 : addressLine1 + " " + addressLine2;
176	        } else {
177	            address = normalizeAddress(ownerFieldsDto.getAddress());
178	        }
179	        List<String> missingFields = new ArrayList<>();
180	        if (isBlank(ownerFieldsDto.getFirstName())) {
181	            missingFields.add("firstName");
182	        }
183	        if (isBlank(ownerFieldsDto.getLastName())) {
184	            missingFields.add("lastName");
185	        }
186	        if (isBlank(address)) {
187	            missingFields.add("address");
188	        }
189	        if (isBlank(ownerFieldsDto.getCity())) {
190	            missingFields.add("city");
191	        }
192	        if (isBlank(ownerFieldsDto.getTelephone())) {
193	            missingFields.add("telephone");
194	        }
195	        if (!missingFields.isEmpty()) {
196	            throw new MissingOwnerFieldsException(missingFields);
197	        }
198	        String telephone = normalizeTelephone(ownerFieldsDto.getTelephone());
199	        boolean sharesHousehold = Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold());
200	        HttpHeaders headers = new HttpHeaders();
201	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
202	        owner.setAddress(address);
203	        owner.setAddressLine1(structured ? addressLine1 : null);
204	        owner.setAddressLine2(structured && !addressLine2.isEmpty() ? addressLine2 : null);
205	        owner.setTelephone(telephone);
206	        validateEmailDomain(owner.getEmail());
207	        validatePostcode(owner.getPostcode(), owner.getRegion());
208	        // The household is keyed deterministically on (lastName, postcode): every owner receives the
209	        // same stable householdId as anyone sharing its normalized last name and postcode, without any
210	        // explicit link. This computed value drives duplicate detection and the household size.
211	        owner.setHouseholdId(householdIdFor(owner.getLastName(), owner.getPostcode()));
212	        // A new owner may join an existing household (same computed householdId); rather than being
213	        // rejected, the joiner is admitted with a capped membership level (see below). The householdId
214	        // no longer feeds duplicate detection.
215	        // Duplicate detection is consolidated into the single derived identity key (telephone, email
216	        // and the last name's Soundex): a create is rejected when the new owner's whole identity key
217	        // equals an existing owner's.
218	        if (isIdentityKeyInUse(owner.getIdentityKey())) {
219	            throw new DuplicateIdentityException(owner.getIdentityKey());
220	        }
221	        if (isCityAtCapacity(owner.getCity())) {
222	            throw new CityAtCapacityException(owner.getCity());
223	        }
224	        if (owner.getRegistrationDate() != null && owner.getRegistrationDate().isAfter(LocalDate.now())) {
225	            throw new FutureRegistrationDateException(owner.getRegistrationDate());
226	        }
227	        LocalDate effectiveDate = owner.getRegistrationDate() != null
228	            ? owner.getRegistrationDate() : LocalDate.now();
229	        LocalDate registrationDate = toBusinessDay(effectiveDate);
230	        if (isDailyRegistrationLimitReached(registrationDate)) {
231	            throw new DailyRegistrationLimitException(registrationDate);
232	        }
233	        owner.setRegistrationDate(registrationDate);
234	        owner.setCustomerCode(deduplicateCustomerCode(customerCodeFor(owner)));
235	        owner.setNamesakeCount(namesakeCount(owner.getFirstName(), owner.getLastName()));
236	        owner.setHouseholdSize(householdSizeAfterCreate(owner.getHouseholdId()));
237	        owner.setMembershipLevel(cappedMembershipLevel(owner));
238	        // A declared household member (one that set 'sharesHousehold' to join an existing household) is
239	        // not a suspected duplicate; otherwise fall back to the soft last-name + postcode match.
240	        Integer possibleDuplicateOf = sharesHousehold ? null : possibleDuplicateOf(owner);
241	        owner.setPossibleDuplicate(possibleDuplicateOf != null);
242	        owner.setPossibleDuplicateOf(possibleDuplicateOf);
243	        this.clinicService.saveOwner(owner);
244	        if (idempotencyKey != null) {
245	            idempotentCreates.put(idempotencyKey, owner.getId());
246	        }
247	        AUDIT.info("owner created id={} customerCode={} registrationDate={} membershipLevel={} membershipNumber={}",
248	            owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate(), owner.getMembershipLevel(),
249	            owner.getMembershipNumber());
250	        AUDIT.info(ownerCreatedEvent(AUDIT_EVENT_SEQ.incrementAndGet(), owner));
251	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
252	        ownerDto.setBulkSignupWarning(isBulkSignupWarning());
253	        ownerDto.setCapacityWarning(isCityApproachingCapacity(owner.getCity()));
254	        headers.setLocation(UriComponentsBuilder.newInstance()
255	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
256	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
257	    }
