358	    private static boolean isBlank(String value) {
359	        return value == null || value.isBlank();
360	    }
361	
362	    /**
363	     * Reads the {@code Idempotency-Key} header from the current request, or {@code null} when the
364	     * header is absent, blank, or there is no bound request. A present, non-blank value is trimmed.
365	     *
366	     * @return the trimmed idempotency key, or {@code null} when none was supplied
367	     */
368	    private static String currentIdempotencyKey() {
369	        RequestAttributes attributes = RequestContextHolder.getRequestAttributes();
370	        if (!(attributes instanceof org.springframework.web.context.request.ServletRequestAttributes servletAttributes)) {
371	            return null;
372	        }
373	        String key = servletAttributes.getRequest().getHeader(IDEMPOTENCY_KEY_HEADER);
374	        return isBlank(key) ? null : key.trim();
375	    }
376	
377	    /**
378	     * The set of disposable email domains that owners may not register with. Compared
379	     * case-insensitively against the domain part of the supplied email.
380	     */
381	    private static final java.util.Set<String> DISPOSABLE_EMAIL_DOMAINS = java.util.Set.of(
382	        "mailinator.com", "tempmail.com", "guerrillamail.com");
383	
384	    /**
385	     * Rejects an owner whose email domain is on the disposable-domain blocklist
386	     * ({@code mailinator.com}, {@code tempmail.com}, {@code guerrillamail.com}). Email is optional:
387	     * a {@code null} or blank value, or one without an {@code '@'} domain part, is accepted here (the
388	     * {@code @Email} Bean Validation constraint governs format). The domain is compared
389	     * case-insensitively; the stored email is already lower-cased.
390	     *
391	     * @param email the owner's email (may be {@code null})
392	     * @throws DisposableEmailDomainException if the email's domain is on the blocklist
393	     */
394	    private static void validateEmailDomain(String email) {
395	        if (isBlank(email)) {
396	            return;
397	        }
398	        int at = email.lastIndexOf('@');
399	        if (at < 0) {
400	            return;
401	        }
402	        String domain = email.substring(at + 1).trim().toLowerCase(java.util.Locale.ROOT);
403	        if (DISPOSABLE_EMAIL_DOMAINS.contains(domain)) {
404	            throw new DisposableEmailDomainException(email);
405	        }
406	    }
407	
408	    /**
409	     * The fixed, region-keyed inclusive 4-digit postcode ranges. A region absent from this table
410	     * (locality {@code UNKNOWN}) imposes no range, so any 4-digit postcode is accepted there.
411	     */
412	    private static final java.util.Map<String, int[]> REGION_POSTCODES = java.util.Map.of(
413	        "NSW", new int[] {2000, 2099},
414	        "VIC", new int[] {3000, 3099},
415	        "QLD", new int[] {4000, 4099});
416	
417	    /**
418	     * Validates a supplied {@code postcode} against the owner's city region. Postcode is optional:
419	     * a {@code null} or blank value is accepted (validation only applies WHEN PRESENT). When
420	     * present, the value has already passed the 4-digit format check (Bean Validation on the
421	     * request body); this enforces that it falls within the inclusive range for the city's region
422	     * (NSW 2000-2099, VIC 3000-3099, QLD 4000-4099). A city with no known region imposes no range.
423	     *
424	     * @param postcode the supplied postcode (may be {@code null})
425	     * @param region the owner's locality/region derived from its city
426	     * @throws InvalidPostcodeException if the postcode is out of range for the region
427	     */
428	    private static void validatePostcode(String postcode, String region) {
429	        if (isBlank(postcode)) {
430	            return;
431	        }
432	        int[] range = REGION_POSTCODES.get(region);
433	        if (range == null) {
434	            return;
435	        }
436	        int value;
437	        try {
438	            value = Integer.parseInt(postcode);
439	        }
440	        catch (NumberFormatException e) {
441	            throw new InvalidPostcodeException(postcode);
442	        }
443	        if (value < range[0] || value > range[1]) {
444	            throw new InvalidPostcodeException(postcode);
445	        }
446	    }
447	
448	    /**
449	     * Normalizes a street address into the canonical form stored on and returned for a newly
450	     * created owner. A {@code null} value becomes the empty string; otherwise surrounding
451	     * whitespace is trimmed, internal runs of whitespace are collapsed to a single space, the
452	     * text is upper-cased, and common street-type abbreviations are expanded on a whole-word
453	     * basis ({@code ST -> STREET}, {@code RD -> ROAD}, {@code AVE -> AVENUE}). The normalized
454	     * value is what gets persisted, echoed back, and used for every address comparison (household
455	     * duplicate detection and the shared household identifier).
456	     *
457	     * @param rawAddress the address value as supplied by the client
458	     * @return the normalized address (possibly empty, never {@code null})
459	     */
460	    private static String normalizeAddress(String rawAddress) {
461	        if (rawAddress == null) {
462	            return "";
463	        }
464	        String collapsed = rawAddress.trim().replaceAll("\\s+", " ").toUpperCase(java.util.Locale.ROOT);
465	        if (collapsed.isEmpty()) {
466	            return "";
467	        }
468	        String[] tokens = collapsed.split(" ");
469	        StringBuilder sb = new StringBuilder(collapsed.length());
470	        for (int i = 0; i < tokens.length; i++) {
471	            String token = tokens[i];
472	            switch (token) {
473	                case "ST" -> token = "STREET";
474	                case "RD" -> token = "ROAD";
475	                case "AVE" -> token = "AVENUE";
476	                default -> { }
477	            }
478	            if (i > 0) {
479	                sb.append(' ');
480	            }
481	            sb.append(token);
482	        }
483	        return sb.toString();
484	    }
485	
486	    /**
487	     * Builds the customer code assigned to a newly created owner. The code is formatted
488	     * {@code <REGION>-<HASH8>} where {@code REGION} is the region derived from the owner's postcode
489	     * (see {@link Owner#getRegion()}) and {@code HASH8} is the first 8 upper-case hex characters of
490	     * the SHA-256 digest of the owner's normalized (E.164) telephone concatenated with its last
491	     * name (e.g. {@code NSW-1A2B3C4D}). No sequence number is involved, so the code depends only on
492	     * the owner's own region and identity.
493	     *
494	     * @param owner the owner being created, with telephone already normalized and postcode/city set
495	     * @return the customer code to assign
496	     */
497	    private static String customerCodeFor(Owner owner) {
498	        return owner.getRegion() + "-" + telephoneNameHash(owner.getTelephone(), owner.getLastName());
499	    }
500	
501	    /**
502	     * The owner's current primary identifier, as carried by the structured audit event. Today this
503	     * is the {@link Owner#getCustomerCode() customerCode}; when the customer code is later unified
504	     * into the member id, this single accessor changes to return the member id, so the emitted event
505	     * automatically carries the new identifier without any change to the event's shape.
506	     *
507	     * @param owner the owner just created
508	     * @return the owner's current primary identifier
509	     */
510	    private static String primaryIdentifier(Owner owner) {
511	        return owner.getCustomerCode();
512	    }
513	
514	    /**
515	     * Renders the immutable structured {@code OWNER_CREATED} audit event as a compact JSON object
516	     * {@code {seq, ownerId, customerCode, membershipLevel, event:'OWNER_CREATED'}}. The
517	     * {@code customerCode} field carries the owner's current {@link #primaryIdentifier(Owner) primary
518	     * identifier}. All values are numeric or a code drawn from {@code [A-Z0-9-]}, so no JSON escaping
519	     * is required.
520	     *
521	     * @param seq   the monotonically increasing event sequence for this create
522	     * @param owner the owner just created
523	     * @return the event serialized as a JSON string
524	     */
525	    private static String ownerCreatedEvent(long seq, Owner owner) {
526	        return String.format(
527	            "{\"seq\":%d,\"ownerId\":%d,\"customerCode\":\"%s\",\"membershipLevel\":%d,\"event\":\"OWNER_CREATED\"}",
528	            seq, owner.getId(), primaryIdentifier(owner), owner.getMembershipLevel());
529	    }
530	
531	    /**
532	     * De-duplicates a freshly computed customer code against the codes already assigned to existing
533	     * owners. When no existing owner carries the given code it is returned unchanged; otherwise the
534	     * smallest suffix {@code -<n>} with {@code n >= 2} that yields a code no existing owner holds is
535	     * appended, guaranteeing distinct owners always receive distinct customer codes.
536	     *
537	     * @param customerCode the customer code computed for the owner being created
538	     * @return the de-duplicated customer code, unique among existing owners
539	     */
540	    private String deduplicateCustomerCode(String customerCode) {
541	        java.util.Set<String> existing = this.clinicService.findAllOwners().stream()
542	            .map(Owner::getCustomerCode)
543	            .filter(java.util.Objects::nonNull)
544	            .collect(java.util.stream.Collectors.toSet());
545	        if (!existing.contains(customerCode)) {
546	            return customerCode;
547	        }
548	        int n = 2;
549	        while (existing.contains(customerCode + "-" + n)) {
550	            n++;
551	        }
552	        return customerCode + "-" + n;
553	    }
554	
555	    /**
556	     * Computes the {@code HASH8} segment of the customer code: the first 8 upper-case hex
557	     * characters of the SHA-256 digest of the normalized (E.164) telephone concatenated with the
558	     * last name.
559	     *
560	     * @param normalizedTelephone the owner's telephone in E.164 form
561	     * @param lastName the owner's last name
562	     * @return the 8-character upper-case hex hash
563	     */
564	    private static String telephoneNameHash(String normalizedTelephone, String lastName) {
565	        String key = (normalizedTelephone == null ? "" : normalizedTelephone)
566	            + (lastName == null ? "" : lastName);
567	        try {
568	            byte[] digest = java.security.MessageDigest.getInstance("SHA-256")
569	                .digest(key.getBytes(java.nio.charset.StandardCharsets.UTF_8));
570	            StringBuilder sb = new StringBuilder(digest.length * 2);
571	            for (byte b : digest) {
572	                sb.append(String.format("%02x", b));
573	            }
574	            return sb.substring(0, 8).toUpperCase(java.util.Locale.ROOT);
575	        }
576	        catch (java.security.NoSuchAlgorithmException e) {
577	            throw new IllegalStateException("SHA-256 not available", e);
578	        }
579	    }
580	
581	    /**
582	     * Normalizes a telephone into E.164 form. Spaces, dashes and brackets are stripped. A value
583	     * already carrying a leading {@code '+'} keeps its country code; otherwise country code
584	     * {@code +61} is assumed and a single leading {@code '0'} is dropped from the national digits.
585	     * The result must carry a leading {@code '+'} followed by 8 to 15 digits, and the length of
586	     * the national number must match the country code: {@code +61} requires 9 national digits and
587	     * {@code +1} requires 10.
588	     *
589	     * @param rawTelephone the telephone value as supplied by the client
590	     * @return the telephone in E.164 form (e.g. {@code +61412345678})
591	     * @throws InvalidTelephoneException if the value cannot form a valid E.164 number
592	     */
593	    private static String normalizeTelephone(String rawTelephone) {
594	        if (rawTelephone == null) {
595	            throw new InvalidTelephoneException(rawTelephone);
596	        }
597	        String cleaned = rawTelephone.replaceAll("[\\s\\-()]", "");
598	        String e164;
599	        if (cleaned.startsWith("+")) {
600	            String digits = cleaned.substring(1);
601	            if (!digits.matches("[0-9]+")) {
602	                throw new InvalidTelephoneException(rawTelephone);
603	            }
604	            e164 = "+" + digits;
605	        } else {
606	            if (!cleaned.matches("[0-9]+")) {
607	                throw new InvalidTelephoneException(rawTelephone);
608	            }
609	            String national = cleaned.startsWith("0") ? cleaned.substring(1) : cleaned;
610	            e164 = "+61" + national;
611	        }
612	        int digitCount = e164.length() - 1;
613	        if (digitCount < 8 || digitCount > 15) {
614	            throw new InvalidTelephoneException(rawTelephone);
615	        }
616	        if (e164.startsWith("+61")) {
617	            if (e164.length() - "+61".length() != 9) {
618	                throw new InvalidTelephoneException(rawTelephone);
619	            }
620	        }
621	        else if (e164.startsWith("+1")) {
622	            if (e164.length() - "+1".length() != 10) {
623	                throw new InvalidTelephoneException(rawTelephone);
624	            }
625	        }
626	        return e164;
627	    }
628	
629	    /**
630	     * Determines whether any existing (non-deleted) owner already carries the given identity key. The
631	     * identity key (the SHA-256 hex over {@code normalizedTelephone + '|' + lowerEmail + '|' +
632	     * soundex(lastName)}) is the single value all duplicate detection is based on, so two owners
633	     * collide only when their whole identity keys are equal.
634	     *
635	     * @param identityKey the identity key of the owner being created
636	     * @return {@code true} if another owner already has the same identity key
637	     */
638	    private boolean isIdentityKeyInUse(String identityKey) {
639	        return this.clinicService.findAllOwners().stream()
640	            .filter(existing -> !existing.isDeleted())
641	            .map(Owner::getIdentityKey)
642	            .anyMatch(identityKey::equals);
643	    }
644	
645	    /**
646	     * Finds an existing owner that the owner being created is a possible (soft) duplicate of: one
647	     * whose last name has the same Soundex code and whose postcode matches, but whose whole identity
648	     * key <em>differs</em> (so it is not a hard duplicate). Because the telephone is part of the
649	     * identity key, two owners sharing a last name (by Soundex) and postcode but carrying different
650	     * telephones fall here rather than being rejected. Such a create is not rejected, but is flagged.
651	     * An owner with no postcode can never be a soft duplicate. When several owners match, the earliest
652	     * (lowest id) is returned so the result is deterministic.
653	     *
654	     * @param owner the owner being created (telephone already normalized, postcode set)
655	     * @return the id of the matching existing owner, or {@code null} when there is no soft match
656	     */
657	    private Integer possibleDuplicateOf(Owner owner) {
658	        if (isBlank(owner.getPostcode())) {
659	            return null;
660	        }
661	        String lastNameSoundex = Owner.soundex(owner.getLastName());
662	        String identityKey = owner.getIdentityKey();
663	        return this.clinicService.findAllOwners().stream()
664	            .filter(existing -> existing.getId() != null
665	                && !existing.isDeleted()
666	                && Owner.soundex(existing.getLastName()).equals(lastNameSoundex)
667	                && owner.getPostcode().equals(existing.getPostcode())
668	                && !identityKey.equals(existing.getIdentityKey()))
669	            .map(Owner::getId)
670	            .min(Integer::compareTo)
671	            .orElse(null);
672	    }
673	
674	    /**
675	     * Counts how many existing owners already share the given first name and last name with the
676	     * owner being created. Both names are compared case-insensitively (after trimming and
677	     * collapsing runs of whitespace). The count reflects the state before the new owner is
678	     * persisted, so a first, otherwise-unique owner yields {@code 0}.
679	     *
680	     * @param firstName the first name of the owner being created
681	     * @param lastName the last name of the owner being created
682	     * @return the number of existing owners sharing the same first and last name
683	     */
684	    private int namesakeCount(String firstName, String lastName) {
685	        String normalizedFirstName = normalizeIdentity(firstName);
686	        String normalizedLastName = normalizeIdentity(lastName);
687	        return (int) this.clinicService.findAllOwners().stream()
688	            .filter(existing -> normalizeIdentity(existing.getFirstName()).equals(normalizedFirstName)
689	                && normalizeIdentity(existing.getLastName()).equals(normalizedLastName))
690	            .count();
691	    }
692	
693	    /**
694	     * Counts how many members the owner being created belongs to in its household, including
695	     * itself, as of this create. Members are the owners sharing the given {@code householdId};
696	     * the new owner is not yet persisted, so its own membership is added to the existing count.
697	     * An owner not assigned to a shared household ({@code householdId} is {@code null}) is a
698	     * household of one.
699	     *
700	     * @param householdId the shared household identifier assigned to the owner being created, or
701	     *                    {@code null} if the owner does not share a household
702	     * @return the number of household members after this create (at least 1)
703	     */
704	    private int householdSizeAfterCreate(String householdId) {
705	        if (householdId == null) {
706	            return 1;
707	        }
708	        long existing = this.clinicService.findAllOwners().stream()
709	            .filter(owner -> householdId.equals(owner.getHouseholdId()))
710	            .count();
711	        return (int) existing + 1;
712	    }
713	
714	    /**
715	     * The maximum number of owners permitted in a single city. Once a city already contains this
716	     * many owners it is considered full and no further owners may be created there.
717	     */
718	    private static final int CITY_CAPACITY = 50;
719	
720	    /**
721	     * Determines whether the given city has already reached its capacity, i.e. already contains
722	     * {@value #CITY_CAPACITY} or more existing owners. Cities are compared case-insensitively after
723	     * collapsing runs of whitespace to a single space and trimming.
724	     *
725	     * @param city the city of the owner being created
726	     * @return {@code true} if the city already contains {@value #CITY_CAPACITY} or more owners
727	     */
728	    private boolean isCityAtCapacity(String city) {
729	        String normalizedCity = normalizeIdentity(city);
730	        long count = this.clinicService.findAllOwners().stream()
731	            .filter(existing -> normalizeIdentity(existing.getCity()).equals(normalizedCity))
732	            .count();
733	        return count >= CITY_CAPACITY;
734	    }
735	
736	    /**
737	     * The number of owners in a city at or above which responses flag a capacity warning. A city
738	     * holding between this many and one below {@link #CITY_CAPACITY} owners is approaching its hard
739	     * limit and its owners' responses carry {@code capacityWarning} true.
740	     */
741	    private static final int CITY_CAPACITY_WARNING_THRESHOLD = 40;
742	
743	    /**
744	     * Determines whether the given city is approaching its capacity, i.e. already contains between
745	     * {@value #CITY_CAPACITY_WARNING_THRESHOLD} and {@value #CITY_CAPACITY} minus one owners
746	     * (inclusive). Cities are compared case-insensitively after collapsing runs of whitespace to a
747	     * single space and trimming, exactly as for the hard capacity check.
748	     *
749	     * @param city the city of the owner whose response is being built
750	     * @return {@code true} if the city holds between {@value #CITY_CAPACITY_WARNING_THRESHOLD} and
751	     *         {@value #CITY_CAPACITY} minus one owners inclusive
752	     */
753	    private boolean isCityApproachingCapacity(String city) {
754	        String normalizedCity = normalizeIdentity(city);
755	        long count = this.clinicService.findAllOwners().stream()
756	            .filter(existing -> normalizeIdentity(existing.getCity()).equals(normalizedCity))
757	            .count();
758	        return count >= CITY_CAPACITY_WARNING_THRESHOLD && count < CITY_CAPACITY;
759	    }
760	
761	    /**
762	     * The maximum number of owners that may be created on any single day. Once this many owners
763	     * already carry a {@code registrationDate} of the current day, no further owners may be created
764	     * that day.
765	     */
766	    private static final int DAILY_REGISTRATION_LIMIT = 100;
767	
768	    /**
769	     * Determines whether the daily registration limit has already been reached, i.e. whether
770	     * {@value #DAILY_REGISTRATION_LIMIT} or more existing owners already carry the given date as
771	     * their {@code registrationDate}.
772	     *
773	     * @param date the current day
774	     * @return {@code true} if {@value #DAILY_REGISTRATION_LIMIT} or more owners were already
775	     *         registered on the given date
776	     */
777	    /**
778	     * The fixed public holidays that the business-day roll skips. A registration date landing on
779	     * any of these is rolled forward, exactly as it is for a weekend.
780	     */
781	    private static final Set<LocalDate> PUBLIC_HOLIDAYS = Set.of(
782	        LocalDate.parse("2026-01-01"), LocalDate.parse("2026-01-26"),
783	        LocalDate.parse("2026-04-25"), LocalDate.parse("2026-12-25"),
784	        LocalDate.parse("2026-12-28"));
785	
786	    /**
787	     * Rolls a registration date forward onto a business day. A date that already falls on a
788	     * weekday which is not a public holiday is returned unchanged; a Saturday, Sunday or listed
789	     * public holiday is rolled forward, one day at a time, until the next non-weekend,
790	     * non-holiday day is reached. This adjusted date is what gets stored as the
791	     * {@code registrationDate} and drives everything derived from it (the fiscal year, the
792	     * membership number's fiscal-year segment, the daily create-limit).
793	     *
794	     * @param date the effective registration date (supplied by the client or defaulted to the
795	     *             server's current date)
796	     * @return the same date if it is a business day, otherwise the next business day that is
797	     *         neither a weekend nor a public holiday
798	     */
799	    private static LocalDate toBusinessDay(LocalDate date) {
800	        while (isNonBusinessDay(date)) {
801	            date = date.plusDays(1);
802	        }
803	        return date;
804	    }
805	
806	    private static boolean isNonBusinessDay(LocalDate date) {
807	        DayOfWeek dayOfWeek = date.getDayOfWeek();
808	        return dayOfWeek == DayOfWeek.SATURDAY || dayOfWeek == DayOfWeek.SUNDAY
809	            || PUBLIC_HOLIDAYS.contains(date);
810	    }
811	
812	    private boolean isDailyRegistrationLimitReached(LocalDate date) {
813	        long count = this.clinicService.findAllOwners().stream()
814	            .filter(existing -> date.equals(existing.getRegistrationDate()))
815	            .count();
816	        return count >= DAILY_REGISTRATION_LIMIT;
817	    }
818	
819	    /**
820	     * The number of owners that may be created on a single day before the bulk-signup warning is
821	     * raised. Once <em>more than</em> this many owners already carry the current business day as
822	     * their {@code registrationDate}, responses flag {@code bulkSignupWarning} true.
823	     */
824	    private static final int BULK_SIGNUP_WARNING_THRESHOLD = 80;
825	
826	    /**
827	     * Determines whether more than {@value #BULK_SIGNUP_WARNING_THRESHOLD} owners have already been
828	     * created today, i.e. already carry the current business day as their {@code registrationDate}.
829	     * This shares the daily create-limit's accumulation path (owners counted by registration date).
830	     *
831	     * @return {@code true} if more than {@value #BULK_SIGNUP_WARNING_THRESHOLD} owners are already
832	     *         registered on today's business day
833	     */
834	    private boolean isBulkSignupWarning() {
835	        LocalDate today = toBusinessDay(LocalDate.now());
836	        long count = this.clinicService.findAllOwners().stream()
837	            .filter(existing -> today.equals(existing.getRegistrationDate()))
838	            .count();
839	        return count > BULK_SIGNUP_WARNING_THRESHOLD;
840	    }
841	
842	    /**
843	     * Computes the membership level to assign to the owner being created, applying the household
844	     * level ceiling: a new owner's level may not exceed one above the current maximum membership
845	     * level among their existing household members. The owner's own naturally derived level (see
846	     * {@link Owner#getComputedMembershipLevel()}) is returned unchanged when there is no existing
847	     * household member; otherwise it is capped at {@code maxHouseholdLevel + 1}. Existing members are
848	     * the non-deleted owners already sharing the owner's {@code householdId}; the owner being created
849	     * is not yet persisted, so it is naturally excluded.
850	     *
851	     * @param owner the owner being created, with {@code householdId} and the fields driving its
852	     *              membership level already set
853	     * @return the (possibly capped) membership level to store on the owner
854	     */
855	    private int cappedMembershipLevel(Owner owner) {
856	        int naturalLevel = owner.getComputedMembershipLevel();
857	        String householdId = owner.getHouseholdId();
858	        if (householdId == null) {
859	            return naturalLevel;
860	        }
861	        java.util.OptionalInt maxHouseholdLevel = this.clinicService.findAllOwners().stream()
862	            .filter(existing -> existing.getId() != null
863	                && !existing.isDeleted()
864	                && householdId.equals(existing.getHouseholdId()))
865	            .mapToInt(Owner::getMembershipLevel)
866	            .max();
867	        if (maxHouseholdLevel.isEmpty()) {
868	            return naturalLevel;
869	        }
870	        return Math.min(naturalLevel, maxHouseholdLevel.getAsInt() + 1);
871	    }
872	
873	    /**
874	     * Derives the stable household identifier for a given last name and postcode. The value is the
875	     * first 12 upper-case hex characters of the SHA-256 digest of {@code normalizedLastName + '|' +
876	     * postcode}, so it is deterministic across calls and identical for every owner sharing the same
877	     * normalized last name and postcode — they belong to the same household automatically.
878	     *
879	     * @param lastName the last name of the household
880	     * @param postcode the postcode of the household (may be {@code null})
881	     * @return the deterministic household identifier
882	     */
883	    private static String householdIdFor(String lastName, String postcode) {
884	        String key = normalizeIdentity(lastName) + "|" + (postcode == null ? "" : postcode);
885	        try {
886	            byte[] digest = java.security.MessageDigest.getInstance("SHA-256")
887	                .digest(key.getBytes(java.nio.charset.StandardCharsets.UTF_8));
888	            StringBuilder sb = new StringBuilder(digest.length * 2);
889	            for (byte b : digest) {
890	                sb.append(String.format("%02x", b));
891	            }
892	            return sb.substring(0, 12).toUpperCase(java.util.Locale.ROOT);
893	        }
894	        catch (java.security.NoSuchAlgorithmException e) {
895	            throw new IllegalStateException("SHA-256 not available", e);
896	        }
897	    }
898	
899	    /**
900	     * Normalizes a text field for household-identity comparison: {@code null} becomes the empty
901	     * string, surrounding whitespace is trimmed, internal runs of whitespace are collapsed to a
902	     * single space, and the result is lower-cased.
903	     *
904	     * @param value the raw field value
905	     * @return the normalized value used for case-insensitive, whitespace-insensitive comparison
906	     */
907	    private static String normalizeIdentity(String value) {
908	        if (value == null) {
909	            return "";
910	        }
911	        return value.trim().replaceAll("\\s+", " ").toLowerCase(java.util.Locale.ROOT);
912	    }
913	}
